"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"
import { Scrollbar } from "@/components/ui/scrollbar"

type DialogContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
  alert: boolean
  titleId: string
  descriptionId: string
}

const DialogContext = React.createContext<DialogContextValue | null>(null)

function useDialog() {
  const ctx = React.useContext(DialogContext)
  if (!ctx) throw new Error("Dialog parts must sit inside <Dialog>.")
  return ctx
}

type DialogProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** A question that needs an answer: role alertdialog, and pointing outside doesn't close it. */
  alert?: boolean
  children: React.ReactNode
}

/** The question, set large. Built on the native <dialog>, so focus, Escape and the top layer are the browser's. */
function Dialog({ open: controlled, defaultOpen = false, onOpenChange, alert = false, children }: DialogProps) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen)
  const open = controlled ?? uncontrolled
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setUncontrolled(next)
      onOpenChange?.(next)
    },
    [controlled, onOpenChange],
  )
  const id = React.useId()
  const value = React.useMemo(
    () => ({ open, setOpen, alert, titleId: `${id}-title`, descriptionId: `${id}-description` }),
    [open, setOpen, alert, id],
  )
  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

function DialogTrigger({ asChild = false, onClick, ...props }: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { open, setOpen } = useDialog()
  const Comp = asChild ? Slot : "button"
  return (
    <Comp
      data-slot="dialog-trigger"
      aria-haspopup="dialog"
      aria-expanded={open}
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) setOpen(true)
      }}
      {...(asChild ? {} : { type: "button" as const })}
      {...props}
    />
  )
}

/**
 * The bare <dialog>, opened as a modal while the Dialog is open. The sheet and
 * the drawer are surfaces too; they bring their own class.
 * Focus goes to the element marked data-autofocus, or the browser's first choice.
 * Taller than the window, it scrolls, on the scrollbar's rail.
 */
function DialogSurface({ className, children, onClick, ...props }: React.ComponentProps<"dialog">) {
  const { open, setOpen, alert, titleId, descriptionId } = useDialog()
  const ref = React.useRef<HTMLDialogElement>(null)

  React.useEffect(() => {
    const d = ref.current
    if (!d) return
    d.setAttribute("closedby", alert ? "closerequest" : "any")
    if (open && !d.open) {
      d.showModal()
      d.querySelector<HTMLElement>("[data-autofocus]")?.focus()
    } else if (!open && d.open) d.close()
  }, [open, alert])

  React.useEffect(() => {
    const d = ref.current
    if (!d) return
    const closed = () => setOpen(false)
    d.addEventListener("close", closed)
    return () => d.removeEventListener("close", closed)
  }, [setOpen])

  return (
    <dialog
      ref={ref}
      role={alert ? "alertdialog" : undefined}
      aria-labelledby={titleId}
      aria-describedby={descriptionId}
      className={className}
      onClick={(e) => {
        onClick?.(e)
        // Pointing outside puts it away (where the browser lacks closedby="any").
        const d = ref.current
        if (alert || !d || e.target !== d) return
        const r = d.getBoundingClientRect()
        if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) d.close()
      }}
      {...props}
    >
      {children}
      <Scrollbar />
    </dialog>
  )
}

type DialogContentProps = React.ComponentProps<"dialog"> & {
  /**
   * frame: corner marks and a row of facts over the question. reply: the question heavy and narrow, the answers
   * set large in the italic, because the answer is yours; use bare DialogClose buttons for them. ruled: a poster's
   * grid of hairlines, the question large on ruled lines, the detail on the far side, the answers in the cells below.
   */
  variant?: "frame" | "reply" | "ruled"
}

function DialogContent({ className, variant = "frame", ...props }: DialogContentProps) {
  return (
    <DialogSurface
      data-slot="dialog-content"
      data-variant={variant === "frame" ? undefined : variant}
      className={cn("db-dialog", className)}
      {...props}
    />
  )
}

/** A frame row over the question: what this is, a hairline, and one fact. */
function DialogMeta({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="dialog-meta" className={cn("db-meta db-dialog-meta", className)} {...props} />
}

function DialogTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDialog()
  return <h2 data-slot="dialog-title" id={titleId} className={cn("db-dialog-title", className)} {...props} />
}

function DialogDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { descriptionId } = useDialog()
  return <p data-slot="dialog-description" id={descriptionId} className={cn("db-dialog-body", className)} {...props} />
}

function DialogActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="dialog-actions" className={cn("db-dialog-actions", className)} {...props} />
}

function DialogClose({ asChild = false, onClick, ...props }: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { setOpen } = useDialog()
  const Comp = asChild ? Slot : "button"
  return (
    <Comp
      data-slot="dialog-close"
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) setOpen(false)
      }}
      {...(asChild ? {} : { type: "button" as const })}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogTrigger,
  DialogSurface,
  DialogContent,
  DialogMeta,
  DialogTitle,
  DialogDescription,
  DialogActions,
  DialogActions as DialogFooter,
  DialogClose,
  useDialog,
  type DialogContentProps,
}

@layer components {
  /* ── db-dialog ── the question, set large */
  .db-dialog {
    border: 0; margin: auto; padding: var(--db-space-8) var(--db-space-7) var(--db-space-7);
    width: min(44rem, calc(100vw - 2 * var(--db-margin))); max-width: none;
    background: var(--db-paper); color: var(--db-graphite);
    --db-corner: 14px;
    opacity: 0; translate: 0 12px;
    transition: opacity var(--db-andante) var(--db-exhale), translate var(--db-andante) var(--db-exhale), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-dialog[open] { opacity: 1; translate: 0 0; }
  @starting-style { .db-dialog[open] { opacity: 0; translate: 0 12px; } }
  :is(.db-dialog, .db-sheet, .db-drawer)::backdrop {
    background: color-mix(in srgb, var(--db-paper) 86%, transparent);
    -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
    opacity: 0;
    transition: opacity var(--db-andante), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  :is(.db-dialog, .db-sheet, .db-drawer)[open]::backdrop { opacity: 1; }
  @starting-style { :is(.db-dialog, .db-sheet, .db-drawer)[open]::backdrop { opacity: 0; } }
  .db-dialog-meta { margin-block-end: var(--db-space-7); }
  .db-dialog[open]::after { animation: db-frame var(--db-andante) var(--db-exhale) 80ms backwards; }
  .db-dialog[open] .db-dialog-meta > hr { transform-origin: 0 50%; animation: db-draw-x var(--db-andante) var(--db-exhale) 200ms backwards; }
  .db-dialog[open] .db-dialog-title { animation: db-breathe-out var(--db-andante) var(--db-exhale) 120ms backwards; }
  @keyframes db-frame { from { opacity: 0; scale: 0.95; } } /* opens out from inside, so the dialog never scrolls */
  @keyframes db-breathe-out { from { opacity: 0; font-weight: 500; font-stretch: 88%; } }
  .db-dialog-title .db-yours { margin-inline-start: 0.06em; } /* Bodoni's italic leans into the word before it at this size */
  .db-dialog-title { font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); font-weight: 300; color: var(--db-ink); }
  .db-dialog-body { margin-block-start: var(--db-space-4); max-inline-size: 40ch; }
  .db-dialog-actions { margin: var(--db-space-7) 0 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--db-space-6); }
  @media (max-width: 40rem) { .db-dialog { padding: var(--db-space-7) var(--db-space-5) var(--db-space-6); } .db-dialog-meta { margin-block-end: var(--db-space-6); } .db-dialog-actions { margin-block-start: var(--db-space-6); gap: var(--db-space-5); } }

  /* Reply ("It has to be design."): the question is ours, heavy and narrow; the answers are yours, set large in the
     italic. The one you point at, or that holds focus, takes a full stop in the accent, and only one ever does. */
  .db-dialog[data-variant][open] .db-dialog-title { animation: none; }
  .db-dialog[data-variant="reply"] .db-dialog-title { font-weight: 800; font-stretch: 72%; line-height: 0.98; letter-spacing: -0.015em; word-spacing: 0.06em; text-wrap: balance; }
  .db-dialog[data-variant="reply"] .db-dialog-actions { justify-content: flex-start; align-items: baseline; column-gap: var(--db-space-7); row-gap: var(--db-space-4); }
  .db-dialog[data-variant="reply"] .db-dialog-actions > button:not(.db-btn) {
    appearance: none; border: 0; padding: 0; background: none; cursor: pointer;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-mf) * var(--db-expression-scale)); line-height: 1; letter-spacing: 0;
    color: var(--db-graphite); transition: color var(--db-allegro) var(--db-breath);
  }
  .db-dialog[data-variant="reply"] .db-dialog-actions > button:not(.db-btn)::after { content: "." / ""; display: inline-block; color: var(--db-accent); scale: 0; transform-origin: 50% 85%; transition: scale var(--db-moderato) var(--db-spiccato); }
  .db-dialog[data-variant="reply"] .db-dialog-actions > button:not(.db-btn):is(:hover, :focus, [data-force~="hover"]) { color: var(--db-ink); }
  .db-dialog[data-variant="reply"] .db-dialog-actions > button:not(.db-btn):is(:hover, :focus, [data-force~="hover"])::after { scale: 1; }
  .db-dialog[data-variant="reply"] .db-dialog-actions:has(> :hover) > button:not(.db-btn, :hover) { color: var(--db-graphite); }
  .db-dialog[data-variant="reply"] .db-dialog-actions:has(> :hover) > button:not(.db-btn, :hover)::after { scale: 0; }

  /* Ruled ("Less is more."): a grid of hairlines to the dialog's edges. Facts in the top corners; the question large,
     each of its lines standing on a rule that draws across as it opens; the detail ragged on the far side; the
     answers in the cells below. */
  .db-dialog[data-variant="ruled"] { --pad: var(--db-space-6); width: min(58rem, calc(100vw - 2 * var(--db-margin))); padding: 0; }
  .db-dialog[data-variant="ruled"][open] { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 16rem); }
  .db-dialog[data-variant="ruled"]::before { content: ""; grid-column: 2; grid-row: 2 / 4; border-inline-start: var(--db-hairline) solid var(--db-ink); pointer-events: none; }
  .db-dialog[data-variant="ruled"] .db-dialog-meta { grid-column: 1 / -1; grid-row: 1; margin: 0; padding: var(--db-space-4) var(--pad); justify-content: space-between; border-block-end: var(--db-hairline) solid var(--db-ink); }
  .db-dialog[data-variant="ruled"] .db-dialog-meta > hr { display: none; }
  .db-dialog[data-variant="ruled"] .db-dialog-title { grid-column: 1; grid-row: 2; position: relative; isolation: isolate; padding: var(--db-space-8) var(--pad) 0; font-size: var(--db-ff); line-height: 1.15; letter-spacing: var(--db-ff-tr); font-weight: 500; }
  .db-dialog[data-variant="ruled"] .db-dialog-title::after { content: ""; position: absolute; z-index: -1; inset: var(--db-space-8) 0 -1px; background: repeating-linear-gradient(to bottom, transparent 0 calc(1lh - 1px), var(--db-ink) calc(1lh - 1px) 1lh); transform-origin: 0 50%; }
  .db-dialog[data-variant="ruled"] .db-dialog-title .db-yours { line-height: 0; } /* the italic mustn't grow a line, or the rules fall out of step */
  :is([dir="rtl"], [dir="rtl"] *).db-dialog[data-variant="ruled"] .db-dialog-title::after { transform-origin: 100% 50%; }
  .db-dialog[data-variant="ruled"][open] .db-dialog-title::after { animation: db-draw-x var(--db-andante) var(--db-exhale) 160ms backwards; }
  .db-dialog[data-variant="ruled"] .db-dialog-body { grid-column: 2; grid-row: 2; align-self: center; margin: 0; padding: var(--db-space-5); max-inline-size: none; text-align: end; text-wrap: pretty; }
  .db-dialog[data-variant="ruled"] .db-dialog-actions { grid-column: 1 / -1; grid-row: 3; margin: 0; display: grid; grid-template-columns: subgrid; align-items: center; gap: 0; border-block-start: var(--db-hairline) solid var(--db-ink); }
  .db-dialog[data-variant="ruled"] .db-dialog-actions > * { grid-column: 1; justify-self: start; margin: var(--db-space-5) var(--pad); }
  .db-dialog[data-variant="ruled"] .db-dialog-actions > :last-child:not(:first-child) { grid-column: 2; justify-self: end; margin-inline: var(--db-space-5); }
  @media (max-width: 40rem) {
    .db-dialog[data-variant="ruled"] { --pad: var(--db-space-5); }
    .db-dialog[data-variant="ruled"][open] { grid-template-columns: minmax(0, 1fr); }
    .db-dialog[data-variant="ruled"]::before { content: none; }
    .db-dialog[data-variant="ruled"] .db-dialog-title { grid-row: auto; padding-block: var(--db-space-7) var(--db-space-5); font-size: var(--db-f); }
    .db-dialog[data-variant="ruled"] .db-dialog-title::after { inset-block: var(--db-space-7) var(--db-space-5); }
    .db-dialog[data-variant="ruled"] .db-dialog-body { grid-column: 1; grid-row: auto; padding: 0 var(--pad) var(--db-space-6); text-align: start; }
    .db-dialog[data-variant="ruled"] .db-dialog-actions { grid-column: 1; grid-row: auto; display: flex; justify-content: space-between; }
    .db-dialog[data-variant="ruled"] .db-dialog-actions > :last-child:not(:first-child) { margin-inline: var(--pad); }
  }
  @media (forced-colors: active) {
    .db-dialog[data-variant="ruled"] .db-dialog-title::after { forced-color-adjust: none; background: repeating-linear-gradient(to bottom, transparent 0 calc(1lh - 1px), CanvasText calc(1lh - 1px) 1lh); }
  }
}
